<?php
namespace App\Http\Controllers\NadiSupport;
use App\Models\NadiChatSession;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
class CsOperationsController extends BaseController {
 public function presence(Request $r){$u=$this->cs($r);$v=$r->validate(['status'=>'required|in:online,busy,offline']);DB::table('nadi_cs_presence')->updateOrInsert(['cs_id'=>$u->id],['status'=>$v['status'],'last_seen_at'=>now(),'updated_at'=>now(),'created_at'=>now()]);return response()->json(['ok'=>true]);}
 public function agents(Request $r){$this->cs($r);$agents=DB::table('nadi_cs_presence')->where('last_seen_at','>=',now()->subMinutes(2))->whereIn('status',['online','busy'])->get(['cs_id','status']);return response()->json(['data'=>$agents]);}
 public function transfer(Request $r,NadiChatSession $session){$actor=$this->cs($r);$v=$r->validate(['target_cs_id'=>'required|integer|min:1','reason'=>'required|string|max:250']);abort_if((int)$v['target_cs_id']===(int)$actor->id,422,'Tujuan harus CS lain.');
  DB::transaction(function()use($session,$actor,$v){$s=NadiChatSession::whereKey($session->id)->lockForUpdate()->firstOrFail();abort_unless($s->status==='active' && (int)$s->assigned_cs_id===(int)$actor->id,403);$candidate=DB::table('nadi_cs_presence')->where('cs_id',$v['target_cs_id'])->where('status','online')->where('last_seen_at','>=',now()->subMinutes(2))->exists();abort_unless($candidate,422,'CS tujuan tidak sedang online.');$old=$s->assigned_cs_id;$s->update(['assigned_cs_id'=>$v['target_cs_id'],'assigned_at'=>now(),'transfer_count'=>$s->transfer_count+1]);$this->event($s->id,$actor->id,'transferred',['from'=>$old,'to'=>$v['target_cs_id'],'reason'=>$v['reason']]);DB::table('nadi_support_notifications')->insert(['cs_id'=>$v['target_cs_id'],'session_id'=>$s->id,'type'=>'transfer','message'=>'Tiket '.$s->ticket.' dialihkan ke Anda','created_at'=>now(),'updated_at'=>now()]);});return response()->json(['ok'=>true]);}
 public function notifications(Request $r){$u=$this->cs($r);return response()->json(['data'=>DB::table('nadi_support_notifications')->where('cs_id',$u->id)->whereNull('read_at')->latest()->limit(30)->get()]);}
 public function read(Request $r,int $id){$u=$this->cs($r);DB::table('nadi_support_notifications')->where('id',$id)->where('cs_id',$u->id)->update(['read_at'=>now()]);return response()->json(['ok'=>true]);}
 public function reports(Request $r){$this->cs($r);$v=$r->validate(['from'=>'nullable|date','to'=>'nullable|date|after_or_equal:from']);$from=$v['from']??now()->subDays(30)->toDateString();$to=$v['to']??today()->toDateString();abort_if(\Carbon\Carbon::parse($from)->diffInDays(\Carbon\Carbon::parse($to))>366,422,'Maksimal 366 hari.');$q=NadiChatSession::whereDate('created_at','>=',$from)->whereDate('created_at','<=',$to);$data=(clone $q)->selectRaw('count(*) as total, sum(case when status = ? then 1 else 0 end) as closed_count, sum(case when status = ? then 1 else 0 end) as waiting_count',['closed','waiting'])->first();$feedback=DB::table('nadi_chat_feedback')->join('nadi_chat_sessions','nadi_chat_feedback.session_id','=','nadi_chat_sessions.id')->whereDate('nadi_chat_sessions.created_at','>=',$from)->whereDate('nadi_chat_sessions.created_at','<=',$to)->selectRaw('count(*) as responses, avg(nadi_chat_feedback.rating) as average_rating')->first();$responded=(clone $q)->whereNotNull('first_response_at')->get(['created_at','first_response_at']);$average=$responded->count()?round($responded->avg(fn($s)=>$s->created_at->diffInSeconds($s->first_response_at))/60,2):null;return response()->json(['period'=>compact('from','to'),'sessions'=>$data,'feedback'=>$feedback,'avg_first_response_minutes'=>$average,'sla_threshold_minutes'=>(int)config('nadi_support.sla_minutes',10)]);}
}
